opts={'A':'YWA','B':'JHL','C':'LJO','D':'OMQ'}
def g(s):
    v=[ord(c)-64 for c in s]
    return ((v[1]-v[0])%26,(v[2]-v[1])%26)
from collections import Counter
c=Counter(g(s) for s in opts.values())
odd=[k for k,s in opts.items() if c[g(s)]==1]
assert odd==['C']
for k in 'ABD': assert k not in odd

t='_VDWY_DWYV_WY_D_'
opts={'A':'YVDVW','B':'YWDVW','C':'YVYVW','D':'YVDVY'}
