import itertools
ring=['O','A','Y','Z']
sols=set()
for p in itertools.permutations(ring):
    nxt=lambda x:p[(p.index(x)+1)%4]
    if nxt('O')=='A' and nxt('Y')=='Z':
        sols.add(p[(p.index('O')+2)%4])
opts={'A':'Z','B':'Y','C':'A','D':'X'}
assert sols=={opts['B']}
for k in 'ACD': assert opts[k] not in sols

import itertools
pts={'P':(185,35),'L':(65,130),'R':(305,130),'A':(125,130),'B':(245,130),'C':(125,230),'D':(245,230),'E':(105,98),'F':(265,98),'O':(185,180)}
lines=[['P','E','L'],['P','F','R'],['L','A'],['B','R'],['P','A'],['P','B'],['E','A'],['F','B'],['A','C'],['B','D'],['C','D'],['A','O','D'],['B','O','C']]
def seg(x,y): return any(x in l and y in l for l in lines)
def col(a,b,c):
    (x1,y1),(x2,y2),(x3,y3)=pts[a],pts[b],pts[c]
    return any(a in l and b in l and c in l for l in lines)
n=sum(1 for a,b,c in itertools.combinations(pts,3) if seg(a,b) and seg(b,c) and seg(a,c) and not col(a,b,c))
